\begin{enumerate}
\item[(a)] A $\Lambda_\infty$-Frobenius algebra is the same as a finite-dimensional unital
	associative algebra $A$ together with a linear functional $\beta_1: A\to\k$ such that:
\begin{enumerate}
\item[(a1)] $\beta_2(a,b)=\beta_1(ab)$ is a non-degenerate, not necessarily symmetric bilinear form
	on $A$.

\item[(a2)] The Nakayama automorphism $F$ of $\beta_2$ is an algebra automorphism of $A$. 
\end{enumerate}

\item[(b)] A $\Lambda_N$-Frobenius algebra is a $\Lambda_\infty$-Frobenius algebra such that $F^N=\Id$. 
\end{enumerate}
\qed

\label{prop:morphisms-Gc}
The set $\Hom_\Gc((I', \Oc(I')), (I, \Oc(I)))$ is in bijection with the set of pairs
$(\psi_*, \psi^*)$, where $\psi_*: I'\to I$ and $\psi^*: \Oc(I)\to\Oc(I')$ are maps of sets such that:
\begin{itemize}
\item[(i)] For every structured frame $f$ of $I$, the unique map $f^*\psi: \{0,1,\dots, n'\}\to \{0,1,\dots, n\}$ making the
diagram
\[
\xymatrix{
\{0,1,\dots,n'\} 
\ar[d]_{\rho(\psi^*f)}\ar[r]^{f^*\psi }& \{0,1,\dots,n\} 
\ar[d]^{\rho(f)}
\\
I'\ar[r]_{\psi_*}&I
}
\]
commutative is given by a morphism in $\Delta$. 

\item[(ii)] For each frame $f$ of $I$ and $g\in\Gen_n$, we have
\[
\psi^*(f .  g) = \psi^*(f) . (f^*\psi)^*(g), 
\]
where $(f^*\psi)^*: \Gen_n\to\Gen_{n'}$ is the map associated to $f^*\psi$ via the simplicial set
$\Gen$. 
\end{itemize}

\label{def:cyclic-order}
Let $J$ be a set. A {\em partial cyclic order} on $J$ is a ternary relation $\lambda \subset J^3$
with the following properties:
\begin{enumerate}[label=(C\arabic{*})]
\item (reflexivity) We have $(a,a,a)\in\lambda$ for any $a\in J$. 

\item (antisymmetry) If  $(a,b,c)\in\lambda$ and $(b,a,c)\in\lambda$, then
$|\{a,b,c\}|\leq 2$. 

 \item (transitivity)  Let $a,b,c,d\in J$ be distinct.
 If $(a,b,c)\in\lambda$ and $(a,c,d)\in\lambda$, then $(a,b,d)\in\lambda$
 and $(b,c,d)\in\lambda$: 

