\label{prop:G-structures}
\begin{enumerate}
\item[(a)] Suppose $\GG$ preserves orientation, and let $S$ be an oriented surface. Then:
\begin{enumerate}
\item[(a1)] For any object $F\in\Gstr^+(S)$, the group $\Aut(F)$ is identified with $K$.

\item[(a2)] The set of isomorphism classes of objects of $\Gstr^+(S)$ is either empty or a torsor
over $H^1(S,K)$.
\end{enumerate}

\item[(b)] Suppose $\GG$ does not preserve orientation, and let  $S$
be any surface. Then: 

\begin{enumerate}
\item[(b1)] For  any object $F\in\Gstr(S)$, the group $\Aut(F)$ is identified with $H^0(S, \underline K^\orr)$. 

\item[(b2)] The set of isomorphism classes of objects of $\Gstr(S)$ is either empty, or is a torsor
over $H^1(S,\underline K^\orr)$.

\item[(b3)] The group  $H^0(S, \underline K^\orr)$ is identified with $K$, if $S$ is orientable, and with
the 2-torsion subgroup $K_2\subset K$, if $S$ is non-orientable. 
\end{enumerate}
\end{enumerate}

A {\em $\GG$-structured marked surface} is a datum consisting of:
\begin{enumerate}
\item[(1)] A compact surface $S$ (possibly with boundary). We denote $S^\circ= S-\partial S$ the interior of $S$.

\item[(2)] A finite subset $M\subset S$.

\item[(3)] A $\GG$-structure $F$ on $S-(M\cap S^\circ)$. 
\end{enumerate}

 A marked surface $(S,M)$ is called {\em stable}, if:
\begin{enumerate}
\item[(1)]  $M\neq\emptyset$ and moreover, $M$ meets each component of $\partial S$.

\item[(2)] $\chi (S^\# - M^\#) < 0$. 
\end{enumerate}

\label{prop:diff-contract}
If $(S,M)$ is a stable $\GG$-structured marked surface, then each component of
$\Diff^\GG(S,M)$ is contractible.

\label{prop:prod-of-grpds}
\begin{enumerate}
\item[(a)] For any surface $S$ we have a natural identification of groupoids
\[
\Gcstr(S) \simeq \Gstr(S)  \times  O(2)_\conf \on{Str}(S). 
\]
\item[(b)] The automorphism group of any object of $O(2)_\conf \on{Str}(S)$ is trivial.
\end{enumerate}

 Parts (a), (b1-2) are obvious. Part (c) was proved by Natanzon \cite{natanzon}
for $\partial S = M=\emptyset$ and Sepp\"al\"a \cite{seppala} for $M=\emptyset$. The extension 
to the case $M\neq\emptyset$ is can be done by the same methods.

