We recall the following definitions from \cite{HSS1}, the first one being a variant of Rezk's
Segal condition \cite{rezk}.

\begin{defi}\label{def:segal} 
Let $\Cb$ be a combinatorial model category, and let $X \in \Cb_\Delta$ be a simplicial object.
\begin{enumerate}
	\item We say that $X$ is {\em 1-Segal} if, for every $n\geq 1$, the morphism
	\[
	f_n: X_n \lra (I[n], X)_R = X_1\times^R_{X_0} X_1 \times^R_{X_0} \cdots \times^R_{X_0} X_1,
	\]
	induced by the embedding $I[n] \hookrightarrow \Delta^n$, is a weak equivalence in $\Cb$. 

	\item We say that $X$ is {\em 2-Segal} if, for every $n\geq 2$ and every triangulation $\Tc$ of $P_{n+1}$,
	the morphism
	\[
	f_\Tc: X_n \lra (\Delta^\Tc, X)_R,
	\]
	induced by the embedding $\Delta^\Tc\hookrightarrow \Delta^n$, is a weak equivalence in $\Cb$. 

\end{enumerate}
\end{defi}

\begin{rem}
	Let $\Cb$ be an ordinary category with limits and colimits. We can equip $\Cb$ with the
	trivial model structure such that the weak equivalences are given by the class of isomorphisms.
	The above Segal conditions then involve underived membrane spaces require the corresponding
	morphisms $f_n$, respectively $f_{\Tc}$, to be isomorphisms in $\Cb$.
\end{rem}

